package netdiag

import (
	"errors"
	"strings"
	"testing"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// topoFixture covers one of every shape the view has a branch for: an up
// interface with errors, a loopback, a default route and a connected one, a
// reachable neighbour and a failed one, and a firewall chain per policy.
func topoFixture() topoDataMsg {
	return topoDataMsg{
		interfaces: []InterfaceInfo{
			{Name: "eth0", State: "UP", Addresses: []string{"192.168.1.5/24"}, MTU: 1500, RxErrors: 3, TxErrors: 0},
			{Name: "lo", State: "LOOP", Addresses: []string{"127.0.0.1/8"}, MTU: 65536},
			{Name: "wlan0", State: "DOWN", MTU: 1500},
		},
		routes: []RouteInfo{
			{Destination: "default", Gateway: "192.168.1.1", Interface: "eth0"},
			{Destination: "192.168.1.0/24", Interface: "eth0"},
		},
		neighbours: []NeighbourInfo{
			{IP: "192.168.1.1", MAC: "aa:bb:cc:dd:ee:ff", Interface: "eth0", State: "REACHABLE"},
			{IP: "192.168.1.9", Interface: "eth0", State: "FAILED"},
		},
		firewall: []FirewallChain{
			{Name: "INPUT", Policy: "DROP", Rules: 12},
			{Name: "FORWARD", Policy: "ACCEPT", Rules: 0},
		},
		firewallSrc: "iptables",
	}
}

// topologyModel returns the parent model on the topology tab, with data loaded.
func topologyModel(t *testing.T) *Model {
	t.Helper()
	m := feed(t, newTestModel(t), testutil.Key("tab"), testutil.Key("tab"))
	return feed(t, m, topoFixture())
}

// ── Loading ──────────────────────────────────────────────────────────────────

func TestTopologyStartsLoading(t *testing.T) {
	m := feed(t, newTestModel(t), testutil.Key("tab"), testutil.Key("tab"))

	if m.topologyModel.state != topoStateLoading {
		t.Errorf("state = %d before any data, want loading", m.topologyModel.state)
	}
	if !strings.Contains(m.View(), "Loading network data") {
		t.Error("the topology tab does not report the first fetch")
	}
}

func TestTopologySpinnerRunsOnlyWhileLoading(t *testing.T) {
	loading := feed(t, newTestModel(t), testutil.Key("tab"), testutil.Key("tab"))

	_, cmd := step(t, loading, spinner.TickMsg{})
	if cmd == nil {
		t.Error("the spinner stopped while the topology data was loading")
	}

	_, cmd = step(t, topologyModel(t), spinner.TickMsg{})
	if cmd != nil {
		t.Error("the spinner kept running after the data arrived")
	}
}

func TestTopologyDataEndsTheLoadingState(t *testing.T) {
	m := topologyModel(t)

	if m.topologyModel.state != topoStateReady {
		t.Errorf("state = %d after the data arrived, want ready", m.topologyModel.state)
	}
	if m.topologyModel.loadErr != "" {
		t.Errorf("loadErr = %q after a successful fetch", m.topologyModel.loadErr)
	}
}

func TestTopologyFetchFailureSurfacesAShortMessage(t *testing.T) {
	m := feed(t, newTestModel(t), testutil.Key("tab"), testutil.Key("tab"))

	m = feed(t, m, topoDataMsg{err: errors.New("no such image")})

	if m.topologyModel.loadErr == "" {
		t.Error("a failed fetch left the error empty")
	}
	if strings.Contains(m.topologyModel.loadErr, "no such image") {
		t.Errorf("loadErr = %q leaks the raw error", m.topologyModel.loadErr)
	}
	// The tab still leaves the loading state, so the user is not stuck on a
	// spinner that will never resolve.
	if m.topologyModel.state != topoStateReady {
		t.Error("a failed fetch left the tab spinning forever")
	}
	if !strings.Contains(m.View(), "Failed to load network data") {
		t.Error("the failure is not shown in the viewport")
	}
}

// ── Rendering ────────────────────────────────────────────────────────────────

func TestTopologyRendersEverySection(t *testing.T) {
	out := topologyModel(t).View()

	for _, want := range []string{"eth0", "192.168.1.5/24", "192.168.1.1", "aa:bb:cc:dd:ee:ff", "INPUT", "iptables"} {
		if !strings.Contains(out, want) {
			t.Errorf("the topology view is missing %q", want)
		}
	}
}

func TestTopologyRendersAnEmptyFetch(t *testing.T) {
	m := feed(t, newTestModel(t), testutil.Key("tab"), testutil.Key("tab"))

	m = feed(t, m, topoDataMsg{firewallSrc: "unavailable"})

	if out := m.View(); out == "" {
		t.Error("the topology view is blank for an empty result")
	}
}

// ── Navigation ───────────────────────────────────────────────────────────────

func TestTopologyScrolling(t *testing.T) {
	m := topologyModel(t)

	m = feed(t, m, testutil.Key("G"))
	atBottom := m.topologyModel.viewport.YOffset

	m = feed(t, m, testutil.Key("g"))
	if m.topologyModel.viewport.YOffset != 0 {
		t.Errorf("YOffset = %d after g, want the top", m.topologyModel.viewport.YOffset)
	}

	m = feed(t, m, testutil.Key("down"))
	if atBottom > 0 && m.topologyModel.viewport.YOffset != 1 {
		t.Errorf("YOffset = %d after down, want 1", m.topologyModel.viewport.YOffset)
	}

	m = feed(t, m, testutil.Key("pgdown"))
	if atBottom > 0 && m.topologyModel.viewport.YOffset <= 1 {
		t.Error("pgdown did not scroll")
	}
}

// Keys must not act on a viewport that has no content yet.
func TestTopologyKeysAreInertWhileLoading(t *testing.T) {
	m := feed(t, newTestModel(t), testutil.Key("tab"), testutil.Key("tab"))

	m, cmd := step(t, m, testutil.Key("ctrl+r"))

	if cmd != nil {
		t.Error("ctrl+r triggered a second fetch while the first was still running")
	}
	if m.topologyModel.state != topoStateLoading {
		t.Error("a key changed the state while loading")
	}
}

func TestTopologyRefreshReturnsToLoading(t *testing.T) {
	m := topologyModel(t)
	m.topologyModel.loadErr = "stale failure"

	m, cmd := step(t, m, testutil.Key("ctrl+r"))

	if m.topologyModel.state != topoStateLoading {
		t.Errorf("state = %d after ctrl+r, want loading", m.topologyModel.state)
	}
	if m.topologyModel.loadErr != "" {
		t.Error("the previous failure survived the refresh")
	}
	if cmd == nil {
		t.Error("ctrl+r issued no fetch")
	}
}

func TestTopologyResizeRebuildsTheViewport(t *testing.T) {
	m := feed(t, topologyModel(t), tea.WindowSizeMsg{Width: 100, Height: 30})

	if m.topologyModel.viewport.Width != 98 {
		t.Errorf("viewport width = %d, want the terminal minus the borders", m.topologyModel.viewport.Width)
	}
	if !strings.Contains(m.View(), "eth0") {
		t.Error("the content was lost on resize")
	}
}

func TestTopologyResizeHasAFloor(t *testing.T) {
	m := feed(t, topologyModel(t), tea.WindowSizeMsg{Width: 5, Height: 1})

	if m.topologyModel.viewport.Width < 20 || m.topologyModel.viewport.Height < 3 {
		t.Errorf("viewport = %dx%d on a tiny terminal, want the floors of 20x3",
			m.topologyModel.viewport.Width, m.topologyModel.viewport.Height)
	}
}

package netdiag

import (
	"strings"
	"testing"
)

// digAnswer is a full dig output with one answer, matching what the DNS test
// returns for a resolvable name.
const digAnswer = `
; <<>> DiG 9.18.24 <<>> google.com
;; global options: +cmd
;; Got answer:
;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41521
;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1

;; OPT PSEUDOSECTION:
; EDNS: version: 0, flags:; udp: 512
;; QUESTION SECTION:
;google.com.			IN	A

;; ANSWER SECTION:
google.com.		217	IN	A	142.250.75.238
google.com.		217	IN	A	142.250.75.174

;; Query time: 2 msec
;; SERVER: 8.8.8.8#53(8.8.8.8) (UDP)
;; WHEN: Sat Aug 02 12:00:00 UTC 2026
;; MSG SIZE  rcvd: 55
`

// digNXDomain is the shape returned for a name that does not exist: a SOA in an
// AUTHORITY section rather than an ANSWER one.
const digNXDomain = `
;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 9110
;; QUESTION SECTION:
;nope.example.			IN	A

;; AUTHORITY SECTION:
example.		900	IN	SOA	ns.example. hostmaster.example. 1 900 900 1800 900

;; Query time: 14 msec
;; SERVER: 1.1.1.1#53(1.1.1.1) (UDP)
`

// digNoAnswer resolves without error but returns nothing — a real case for
// AAAA lookups on IPv4-only hosts.
const digNoAnswer = `
;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 3
;; QUESTION SECTION:
;example.com.			IN	AAAA

;; Query time: 5 msec
;; SERVER: 8.8.8.8#53(8.8.8.8) (UDP)
`

// ── Parsing ──────────────────────────────────────────────────────────────────

func TestParseDNSOutputExtractsEveryField(t *testing.T) {
	res := parseDNSOutput(digAnswer)

	if res.status != "NOERROR" {
		t.Errorf("status = %q, want NOERROR", res.status)
	}
	if res.question != "google.com  A" {
		t.Errorf("question = %q, want \"google.com  A\"", res.question)
	}
	if res.queryTime != "2 ms" {
		t.Errorf("queryTime = %q, want \"2 ms\"", res.queryTime)
	}
	// The parenthesised repeat of the address is noise and must be dropped.
	if res.server != "8.8.8.8#53" {
		t.Errorf("server = %q, want \"8.8.8.8#53\" without the trailing parenthesis", res.server)
	}
	if len(res.answers) != 2 {
		t.Fatalf("%d answers parsed, want 2", len(res.answers))
	}

	first := res.answers[0]
	if first.name != "google.com" {
		t.Errorf("answer name = %q, want the trailing dot stripped", first.name)
	}
	if first.ttl != "217" || first.rtype != "A" || first.value != "142.250.75.238" {
		t.Errorf("answer = %+v, want ttl 217, type A, value 142.250.75.238", first)
	}
}

// Records outside the ANSWER section must not be collected: an NXDOMAIN's SOA
// would otherwise be shown as if it were an answer.
func TestParseDNSOutputIgnoresOtherSections(t *testing.T) {
	res := parseDNSOutput(digNXDomain)

	if res.status != "NXDOMAIN" {
		t.Errorf("status = %q, want NXDOMAIN", res.status)
	}
	if len(res.answers) != 0 {
		t.Errorf("%d answers parsed from an NXDOMAIN reply, want none: %+v", len(res.answers), res.answers)
	}
	if res.question != "nope.example  A" {
		t.Errorf("question = %q, want it parsed even without answers", res.question)
	}
}

func TestParseDNSOutputHandlesJunk(t *testing.T) {
	for _, tc := range []struct {
		name   string
		output string
	}{
		{"empty", ""},
		{"not dig output at all", "connection timed out; no servers could be reached"},
		{"truncated mid-section", ";; ANSWER SECTION:\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			res := parseDNSOutput(tc.output)

			if len(res.answers) != 0 {
				t.Errorf("answers = %+v, want none", res.answers)
			}
		})
	}
}

// ── Formatting ───────────────────────────────────────────────────────────────

func TestFormatDNSOutputShowsAnswers(t *testing.T) {
	out := strings.Join(formatDNSOutput(digAnswer, 80), "\n")

	for _, want := range []string{"NOERROR", "google.com", "142.250.75.238", "TTL 217s", "2 ms", "8.8.8.8#53"} {
		if !strings.Contains(out, want) {
			t.Errorf("the formatted output is missing %q", want)
		}
	}
	if !strings.Contains(out, "Answers") {
		t.Error("the answers section is not labelled")
	}
}

// A successful lookup with nothing to show has to say so, rather than render an
// empty section the user cannot distinguish from a rendering bug.
func TestFormatDNSOutputMarksAnEmptyAnswerSection(t *testing.T) {
	out := strings.Join(formatDNSOutput(digNoAnswer, 80), "\n")

	if !strings.Contains(out, "(none)") {
		t.Errorf("a NOERROR reply with no answers does not say so:\n%s", out)
	}
}

// A failed lookup shows the status, and must not claim an empty answer section
// — there is nothing to answer.
func TestFormatDNSOutputOnFailure(t *testing.T) {
	out := strings.Join(formatDNSOutput(digNXDomain, 80), "\n")

	if !strings.Contains(out, "NXDOMAIN") {
		t.Error("the failure status is not shown")
	}
	if strings.Contains(out, "(none)") {
		t.Error("an NXDOMAIN reply rendered an empty answers section")
	}
}

func TestFormatDNSOutputOnJunk(t *testing.T) {
	out := strings.Join(formatDNSOutput("connection timed out", 80), "\n")

	if !strings.Contains(out, "unknown") {
		t.Errorf("output with no parsable status does not fall back to \"unknown\":\n%s", out)
	}
}

// Every line is padded to the viewport width, so the details background is
// uniform (Rule 115).
func TestFormatDNSOutputPadsEveryLine(t *testing.T) {
	const width = 60

	for i, line := range formatDNSOutput(digAnswer, width) {
		if got := len([]rune(stripANSI(line))); got != width {
			t.Errorf("line %d is %d runes wide, want %d", i, got, width)
		}
	}
}

// The icon has to distinguish the three outcomes: a resolved name, a name that
// resolved to nothing, and a failure.
func TestDNSStatusIconDistinguishesOutcomes(t *testing.T) {
	resolved := dnsStatusIcon("NOERROR", 2)
	empty := dnsStatusIcon("NOERROR", 0)
	failed := dnsStatusIcon("NXDOMAIN", 0)

	if resolved == empty {
		t.Error("a resolved name and an empty answer share an icon")
	}
	if empty == failed {
		t.Error("an empty answer and a failure share an icon")
	}
	for _, icon := range []string{resolved, empty, failed} {
		if icon == "" {
			t.Error("dnsStatusIcon returned nothing")
		}
	}
}

// stripANSI removes escape sequences so widths can be measured. Under `go test`
// lipgloss emits none, but the helper keeps the assertion honest if that ever
// changes.
func stripANSI(s string) string {
	var b strings.Builder
	inEscape := false
	for _, r := range s {
		switch {
		case r == '\x1b':
			inEscape = true
		case inEscape && r == 'm':
			inEscape = false
		case !inEscape:
			b.WriteRune(r)
		}
	}
	return b.String()
}

